  ulong t3 = fd_ed25519_serial_madd52lo( t1, a->limb[1], a->limb[4] );  /* < 2^53 */
  ulong t4 = fd_ed25519_serial_madd52hi( z2, a->limb[1], a->limb[3] );  /* < 2^52 */
  ulong t5 = fd_ed25519_serial_madd52hi( t4, a->limb[0], a->limb[4] );  /* < 2^53 */
  ulong t6 = t5 << 1;  /* < 2^54 */
  ulong t7 = fd_ed25519_serial_madd52hi( t6, a->limb[2], a->limb[2] );  /* < 2^55 */
  ulong t8 = t3 + t7;  /* < 2^55 */
  ulong t9 = t8 << 1;  /* < 2^56 */
  ulong c11 = 19UL;
  FD_ED25519_LANE_OPAQUE( c11 );
  ulong t10 = c11 * t9;  /* < 2^61 */
  ulong t12 = fd_ed25519_serial_madd52lo( t10, a->limb[0], a->limb[0] );  /* < 2^61 */
  ulong t13 = t12 & 2251799813685247UL;  /* < 2^51 */
  ulong t14 = fd_ed25519_serial_madd52lo( z2, a->limb[1], a->limb[3] );  /* < 2^52 */
  ulong t15 = fd_ed25519_serial_madd52lo( t14, a->limb[0], a->limb[4] );  /* < 2^53 */
  ulong t16 = fd_ed25519_serial_madd52hi( z2, a->limb[1], a->limb[2] );  /* < 2^52 */
  ulong t17 = fd_ed25519_serial_madd52hi( t16, a->limb[0], a->limb[3] );  /* < 2^53 */
  ulong t18 = t17 << 1;  /* < 2^54 */
  ulong t19 = t15 + t18;  /* < 2^55 */
  ulong t20 = t19 << 1;  /* < 2^56 */
  ulong t21 = fd_ed25519_serial_madd52lo( t20, a->limb[2], a->limb[2] );  /* < 2^56 */
  ulong t22 = fd_ed25519_serial_madd52hi( z2, a->limb[4], a->limb[4] );  /* < 2^52 */
  ulong t23 = t22 << 1;  /* < 2^53 */
  ulong t24 = c11 * t23;  /* < 2^58 */
  ulong t25 = t21 + t24;  /* < 2^58 */
  ulong t26 = t25 >> 51;  /* < 2^7 */
  ulong t27 = fd_ed25519_serial_madd52lo( t13, c11, t26 );  /* < 2^52 */
  ulong t28 = t12 >> 51;  /* < 2^10 */
  ulong t29 = fd_ed25519_serial_madd52lo( z2, a->limb[0], a->limb[1] );  /* < 2^52 */
  ulong t30 = fd_ed25519_serial_madd52hi( t29, a->limb[0], a->limb[0] );  /* < 2^53 */
  ulong t31 = t30 << 1;  /* < 2^54 */
  ulong t32 = fd_ed25519_serial_madd52hi( z2, a->limb[2], a->limb[3] );  /* < 2^52 */
  ulong t33 = fd_ed25519_serial_madd52hi( t32, a->limb[1], a->limb[4] );  /* < 2^53 */
  ulong t34 = t33 << 1;  /* < 2^54 */
  ulong t35 = fd_ed25519_serial_madd52lo( t34, a->limb[2], a->limb[4] );  /* < 2^55 */
  ulong t36 = t35 << 1;  /* < 2^56 */
  ulong t37 = fd_ed25519_serial_madd52lo( t36, a->limb[3], a->limb[3] );  /* < 2^56 */
  ulong t38 = c11 * t37;  /* < 2^60 */
