  ulong t44 = t43 << 1;  /* < 2^53 */
  ulong t45 = fd_ed25519_serial_madd52lo( t44, a->limb[0], a->limb[2] );  /* < 2^54 */
  ulong t46 = t45 << 1;  /* < 2^55 */
  ulong t47 = fd_ed25519_serial_madd52lo( t46, a->limb[1], a->limb[1] );  /* < 2^55 */
  ulong t48 = fd_ed25519_serial_madd52hi( z2, a->limb[2], a->limb[4] );  /* < 2^52 */
